WITH scored AS (SELECT id, store_id, RANK() OVER (PARTITION BY product_id, store_id ORDER BY revenue DESC NULLS LAST) AS revenue_rank, ROUND(units / SUM(units) OVER (PARTITION BY store_id, product_id), 4) AS units_share, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY sale_date, id) AS seq_no FROM store_sales WHERE revenue >= 2800) SELECT CASE WHEN units_share >= 0.79 THEN 'HIGH' ELSE 'LOW' END AS units_share_tier, seq_no, PERCENTILE_APPROX(units_share, 0.9) AS units_share_p90, ROUND(AVG(seq_no), 2) AS avg_seq_no FROM scored GROUP BY CASE WHEN units_share >= 0.79 THEN 'HIGH' ELSE 'LOW' END, seq_no HAVING PERCENTILE_APPROX(units_share, 0.9) > 0 ORDER BY units_share_p90
